-- RCMP database schema for PostgreSQL 16 / Supabase.
-- GENERATED by "npm run schema" from server/db.js. Do not edit by hand.
--
-- How to use: Supabase dashboard > SQL Editor > New query > paste this file > Run.
-- It is safe to run more than once (every statement is IF NOT EXISTS / idempotent).
-- The server also creates these tables itself on start-up, so this file is optional,
-- but running it first lets you check the database before deploying.

CREATE TABLE IF NOT EXISTS users (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('student','researcher','mentor','admin')),
  status TEXT NOT NULL CHECK (status IN ('active','suspended')),
  data JSONB NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_users_email ON users (lower(email));
CREATE TABLE IF NOT EXISTS projects (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('draft','open','paused','closed')),
  visibility TEXT NOT NULL CHECK (visibility IN ('public','summary','private')),
  data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_projects_owner ON projects(owner_id);
CREATE TABLE IF NOT EXISTS project_members (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  PRIMARY KEY (project_id, user_id)
);
CREATE INDEX IF NOT EXISTS ix_members_user ON project_members(user_id);
CREATE TABLE IF NOT EXISTS requests (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  from_id TEXT NOT NULL,
  to_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('interest','invitation')),
  status TEXT NOT NULL CHECK (status IN ('pending','accepted','declined','withdrawn')),
  data JSONB NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_request_one_pending ON requests(project_id, from_id, to_id, type) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS ix_requests_to ON requests(to_id, status);
CREATE TABLE IF NOT EXISTS agreements (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  version INTEGER NOT NULL CHECK (version >= 1),
  status TEXT NOT NULL,
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS tasks (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  status TEXT NOT NULL CHECK (status IN ('todo','progress','review','done')),
  data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_tasks_project ON tasks(project_id);
CREATE TABLE IF NOT EXISTS files (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  size BIGINT NOT NULL CHECK (size > 0 AND size <= 10485760),
  data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_files_project ON files(project_id);
CREATE TABLE IF NOT EXISTS activity (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS mentor_requests (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  mentor_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending','accepted','declined','clarify','withdrawn','completed')),
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS support_requests (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  researcher_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('pending','assigned','in_progress','completed','reopened','rejected')),
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS subscriptions (
  id TEXT PRIMARY KEY,
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS billing_events (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('succeeded','failed','pending')),
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS statements (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  researcher_id TEXT NOT NULL,
  period TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('draft','awaiting_approval','approved','paid','payout_failed')),
  data JSONB NOT NULL,
  UNIQUE (researcher_id, period)
);
CREATE TABLE IF NOT EXISTS reports (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('open','dismissed','actioned')),
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS contact_messages (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('new','read','answered')),
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_log (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS notifications (
  seq BIGINT GENERATED ALWAYS AS IDENTITY,
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_notifications_user ON notifications(user_id);
CREATE TABLE IF NOT EXISTS notification_prefs (
  id TEXT PRIMARY KEY,
  data JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS meta (
  id TEXT PRIMARY KEY,
  data JSONB NOT NULL
);

-- ---------------------------------------------------------------------------
-- Security for Supabase. Supabase exposes every table in the "public" schema
-- through its REST API using the public "anon" key. RCMP never uses that API:
-- the Node server connects directly as the database owner (which bypasses
-- row level security). Enabling RLS with no policies, and revoking the API
-- roles, means nobody holding the anon key can read or change any row.
-- ---------------------------------------------------------------------------
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agreements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.files ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mentor_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.statements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_prefs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.meta ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON public.users FROM anon, authenticated;
    REVOKE ALL ON public.projects FROM anon, authenticated;
    REVOKE ALL ON public.project_members FROM anon, authenticated;
    REVOKE ALL ON public.requests FROM anon, authenticated;
    REVOKE ALL ON public.agreements FROM anon, authenticated;
    REVOKE ALL ON public.tasks FROM anon, authenticated;
    REVOKE ALL ON public.files FROM anon, authenticated;
    REVOKE ALL ON public.activity FROM anon, authenticated;
    REVOKE ALL ON public.mentor_requests FROM anon, authenticated;
    REVOKE ALL ON public.support_requests FROM anon, authenticated;
    REVOKE ALL ON public.subscriptions FROM anon, authenticated;
    REVOKE ALL ON public.billing_events FROM anon, authenticated;
    REVOKE ALL ON public.statements FROM anon, authenticated;
    REVOKE ALL ON public.reports FROM anon, authenticated;
    REVOKE ALL ON public.contact_messages FROM anon, authenticated;
    REVOKE ALL ON public.audit_log FROM anon, authenticated;
    REVOKE ALL ON public.notifications FROM anon, authenticated;
    REVOKE ALL ON public.notification_prefs FROM anon, authenticated;
    REVOKE ALL ON public.meta FROM anon, authenticated;
  END IF;
END $$;
